class Solution {
    public long[] kthPalindrome(int[] queries, int intLength) {
        int L = (intLength + 1) / 2;
        long start = (long) Math.pow(10, L - 1);
        long limit = (long) Math.pow(10, L);
        long[] ans = new long[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long val = start + queries[i] - 1;
            if (val >= limit) {
                ans[i] = -1;
            } else {
                String s = Long.toString(val);
                StringBuilder sb = new StringBuilder(s).reverse();
                String pal = s + (intLength % 2 == 1 ? sb.substring(1) : sb.toString());
                ans[i] = Long.parseLong(pal);
            }
        }
        return ans;
    }
}

