var kthPalindrome = function(queries, intLength) {
    const L = Math.floor((intLength + 1) / 2);
    const start = 10n ** BigInt(L - 1);
    const limit = 10n ** BigInt(L);
    const ans = [];
    for (const q of queries) {
        const val = start + BigInt(q) - 1n;
        if (val >= limit) {
            ans.push(-1);
        } else {
            const s = val.toString();
            const rev = s.split('').reverse().join('');
            const pal = s + (intLength % 2 === 1 ? rev.slice(1) : rev);
            ans.push(Number(pal));
        }
    }
    return ans;
};
